// Adjusted iterative process to improve convergence
double result = 0.5 * (1.0 + Erf.erf((x - mean) / (standardDeviation * Math.sqrt(2.0))));
int maxIterations = 1000;
int iter = 0;
while (Math.abs(result - previousResult) > 1e-12 && iter < maxIterations) {
    previousResult = result;
    result = 0.5 * (1.0 + Erf.erf((x - mean) / (standardDeviation * Math.sqrt(2.0))));
    iter++;
}
if (iter >= maxIterations) {
    throw new MaxIterationsExceededException(maxIterations);
}
return result;

